/***
 * MARK: itemCardClass
 * @description Resolves the card border/background styling for a queue item.
 * @param {boolean} active
 * @param {boolean} waiting
 * @param {boolean} blocked
 * @returns {string}
 * @example itemCardClass(true, false, false) // => 'bg-emerald-950/30 ...'
 ***/
const itemCardClass = (active, waiting, blocked) => {
  if (active)
    return 'bg-emerald-950/30 border-emerald-500/70 shadow-[0_0_12px_rgba(16,185,129,0.15)]';
  if (waiting) return 'bg-amber-950/20 border-amber-500/50';
  if (blocked) return 'bg-slate-900/60 border-rose-900/40 opacity-70';
  return 'bg-slate-900/80 border-slate-800 hover:border-slate-700';
};

/***
 * MARK: itemBadgeClass
 * @description Resolves the priority tag badge class for a queue item.
 * @param {boolean} active
 * @param {boolean} waiting
 * @param {boolean} blocked
 * @returns {string}
 * @example itemBadgeClass(false, false, true) // => 'bg-rose-950 text-rose-300 ...'
 ***/
const itemBadgeClass = (active, waiting, blocked) => {
  if (active) return 'bg-emerald-950 text-emerald-400 border-emerald-500/50 animate-pulse';
  if (waiting) return 'bg-amber-950 text-amber-300 border-amber-500/50';
  if (blocked) return 'bg-rose-950 text-rose-300 border-rose-500/50';
  return 'bg-slate-800 text-slate-300 border-slate-700';
};

/***
 * MARK: QueueOrderList
 * @description Presentational queue list: renders the autonomous execution queue
 * in dispatch order (#1, #2, #3, ...) with stage progress, priority reasoning,
 * project tags, dependency warning indicators, and a blocked/waiting reason.
 * Pure presentation: data comes in via `items` (the monitor widget passes it
 * as `scheduledQueue`); row activation is surfaced through
 * `onSelectTask(item)`, so callers can open an inspector or perform other
 * actions. `schedulerRunning` drives the empty-state wording; `compact` is
 * reserved for dense surfaces.
 * @example <QueueOrderList items={queue} engineState={engineState} onSelectTask={openTask} />
 * @param {Array<Object>} [props.items] - Ordered queue items.
 * @param {Array<Object>} [props.scheduledQueue] - Alias for `items` (monitor widget's historical prop name).
 * @param {Object} [props.engineState] - Engine state (drives the single-active invariant).
 * @param {boolean} [props.schedulerRunning] - False shows a stopped empty state.
 * @param {Function} [props.onSelectTask] - Called with the clicked queue item.
 * @param {boolean} [props.compact] - Density hint (currently cosmetic).
 * @returns {JSX.Element}
 ***/
export function QueueOrderList({
  items,
  scheduledQueue,
  engineState = {},
  schedulerRunning,
  onSelectTask,
  compact = false,
}) {
  const resolvedItems = Array.isArray(items)
    ? items
    : Array.isArray(scheduledQueue)
      ? scheduledQueue
      : [];

  const handleSelect = typeof onSelectTask === 'function' ? onSelectTask : null;
  const schedulerStopped = schedulerRunning === false;
  // Rows are interactive only when a selection handler is wired (the queue
  // popup opens the inspector); handler-less surfaces like the monitor keep
  // the original plain-div rows — never focusable buttons that do nothing.
  const interactive = typeof handleSelect === 'function';

  const handleRowKeyDown = (event, item) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      handleSelect(item);
    }
  };

  const emptyState = (
    <div
      className={`h-full flex flex-col items-center justify-center p-6 text-center text-slate-400 font-mono ${
        compact ? 'text-[10px]' : 'text-xs'
      }`}
    >
      <span className="text-3xl mb-2 opacity-50">✨</span>
      <p className="font-bold text-slate-300">
        {schedulerStopped ? 'Scheduler Stopped' : 'Queue is Clear'}
      </p>
      <p className="text-[11px] mt-1 text-slate-400">
        {schedulerStopped
          ? 'Autonomous execution is off. Start the scheduler to resume pickup.'
          : 'Idle — waiting for work. New tasks dispatch automatically.'}
      </p>
    </div>
  );

  return (
    <div
      // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- keyboard-scrollable widget body (WCAG 2.1.1)
      tabIndex={0}
      role="group"
      aria-label="Queue order list"
      className={`flex-1 p-2.5 space-y-2 overflow-y-auto custom-scrollbar bg-[#080c16] ${
        compact ? 'p-1.5 space-y-1.5' : ''
      }`}
    >
      {resolvedItems.length === 0
        ? emptyState
        : resolvedItems.map((item, idx) => {
        const isItemActive =
          engineState?.status === 'running' &&
          engineState?.activeTaskId != null &&
          String(item.id) === String(engineState.activeTaskId);
        const isBlocked = item.isBlocked || item.status === 'blocked';
        const isWaiting = item.status === 'waiting_human';
        const reason =
          item.priorityReason ||
          item.waitingReason ||
          item.blockedReason ||
          item.blocker ||
          'Queued';

        return (
          <div
            key={item.id || idx}
            data-testid={`queue-item-${item.id}`}
            {...(interactive
              ? {
                  role: 'button',
                  tabIndex: 0,
                  onClick: () => handleSelect(item),
                  onKeyDown: (event) => handleRowKeyDown(event, item),
                }
              : {})}
            className={`p-2.5 rounded-md border backdrop relative overflow-hidden ${interactive ? 'cursor-pointer ' : ''}${itemCardClass(
              isItemActive,
              isWaiting,
              isBlocked,
            )}`}
          >
            {/* Header Row: Rank Badge + Priority Tag */}
            <div className="flex items-center justify-between gap-2 mb-1.5">
              <div className="flex items-center gap-1.5 min-w-0">
                <span
                  className={`w-5 h-5 rounded flex items-center justify-center text-[10px] font-mono font-black shrink-0 ${
                    isItemActive
                      ? 'bg-emerald-500 text-slate-950 shadow-sm'
                      : 'bg-slate-800 text-slate-300'
                  }`}
                >
                  #{item.queueOrder || idx + 1}
                </span>
                <span className="text-[10px] font-mono text-slate-400 uppercase font-semibold truncate">
                  {item.projectName || 'Project'}
                </span>
              </div>

              <span
                className={`text-[9px] px-1.5 py-0.2 rounded border font-mono uppercase tracking-wider shrink-0 ${itemBadgeClass(
                  isItemActive,
                  isWaiting,
                  isBlocked,
                )}`}
              >
                {reason}
              </span>
            </div>

            {/* Task Title */}
            <h4 className="text-xs font-bold text-slate-100 line-clamp-2 leading-tight">
              {formatTaskTitleFirstLine(item)}
            </h4>

            {/* Task Metadata Footer */}
            <div className="mt-2 pt-1.5 border-t border-slate-800/80 flex items-center justify-between text-[10px] font-mono text-slate-400">
              <span className="flex items-center gap-1 text-slate-300 truncate max-w-[70%]">
                <span className="text-emerald-400">▸</span>
                <span className="truncate">{item.currentStageName || 'Stage'}</span>
              </span>
              <span className="shrink-0">KB-{item.id?.slice(0, 4)?.toUpperCase() || 'TASK'}</span>
            </div>

            {isItemActive && (
              <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-emerald-500" />
            )}
          </div>
        );
      })}
    </div>
  );
}

/***
 * MARK: QueueOrderList default
 * @description Default export alias for QueueOrderList.
 * @example <QueueOrderList items={queue} />
 ***/
export default QueueOrderList;

/***
 * MARK: KpiCard
 * @description The one KPI card atom every KPI widget is built from: a compact
 *   gradient card with a label row, a headline value with an optional unit,
 *   a sub-line, and a coloured footer bar. The composite KPI Ribbon and the
 *   five atomic KPI widgets all render this exact component, so splitting a
 *   ribbon into atoms cannot drift the visuals.
 *
 *   When `children` is provided it replaces the value/unit/sub block, which is
 *   how the Active Engine card renders its multi-line stage / alias / model
 *   body inside the same shell.
 ***/

/***
 * MARK: KPI_CARD_ACCENTS
 * @description Per-accent class strings, kept verbatim from the original KPI
 *   ribbon so the composite stays pixel-identical after the split.
 ***/
const KPI_CARD_ACCENTS = new Map([
  [
    'emerald',
    {
      card: 'bg-gradient-to-b from-emerald-950/40 to-slate-900/90 border border-emerald-500/30',
      label: 'text-emerald-400',
      value: 'text-emerald-400',
      unit: 'text-[10px] font-mono font-bold text-emerald-300/80',
      bar: 'bg-emerald-500/50',
    },
  ],
  [
    'rose',
    {
      card: 'bg-gradient-to-b from-rose-950/40 to-slate-900/90 border border-rose-500/30',
      // WCAG 1.4.6 AAA (7:1): rose-400 measured 6.69-6.88:1 over this card's
      // gradient; the same-hue step to rose-300 holds 9.5:1+ and rose-200/80
      // 8.4:1+ for the dimmed unit line (locked by observabilityContrast.test.js).
      label: 'text-rose-300',
      value: 'text-rose-300',
      unit: 'text-[10px] font-mono font-bold text-rose-200/80',
      bar: 'bg-rose-500/50',
    },
  ],
  [
    'cyan',
    {
      card: 'bg-gradient-to-b from-cyan-950/40 to-slate-900/90 border border-cyan-500/30',
      label: 'text-cyan-400',
      value: 'text-cyan-400',
      unit: 'text-[10px] font-mono text-cyan-300/80',
      bar: 'bg-cyan-500/50',
    },
  ],
  [
    'amber',
    {
      card: 'bg-gradient-to-b from-amber-950/40 to-slate-900/90 border border-amber-500/30',
      label: 'text-amber-400',
      value: 'text-amber-400',
      unit: 'text-[10px] font-mono text-amber-300/80',
      bar: 'bg-amber-500/50',
    },
  ],
  [
    'indigo',
    {
      card: 'bg-gradient-to-b from-indigo-950/40 to-slate-900/90 border border-indigo-500/30',
      // WCAG 1.4.6 AAA (7:1): indigo-400 measured 6.00-6.08:1 over this card's
      // gradient (the regression the 2026-09-20 register fixed in the ribbon
      // and the atom split reintroduced); indigo-300 holds 9:1+ and
      // indigo-200/80 8:1+ for the dimmed unit line.
      label: 'text-indigo-300',
      value: 'text-indigo-300',
      unit: 'text-[10px] font-mono text-indigo-200/80',
      bar: 'bg-indigo-500/50',
    },
  ],
]);

/***
 * MARK: KpiCard
 * @description Renders one KPI card.
 * @example <KpiCard label="✓ Successes" value={7} unit="(87.5%)" sub="Completed tasks" icon="🏆" accent="emerald" testId="kpi-successes" />
 * @example <KpiCard label="⚙️ Active engine" icon="🤖" accent="indigo" testId="kpi-pipeline"><span>Build</span></KpiCard>
 * @param {Object} props - Card content and styling.
 * @param {string} props.label - Card label (rendered uppercase by CSS).
 * @param {number|string} [props.value] - Headline value.
 * @param {string} [props.unit] - Short unit / rate shown beside the value.
 * @param {string} [props.sub] - Truncated sub-line under the value.
 * @param {string} [props.icon] - Emoji shown opposite the label.
 * @param {'emerald'|'rose'|'cyan'|'amber'|'indigo'} [props.accent] - Colour theme.
 * @param {string} [props.testId] - DOM test id for this card.
 * @param {boolean} [props.footerBar] - Whether to render the coloured footer bar.
 * @param {string} [props.className] - Extra classes (e.g. grid column span).
 * @param {ReactNode} [props.children] - Custom body replacing value/unit/sub.
 * @returns {ReactElement} The card.
 ***/
export function KpiCard({
  label,
  value,
  unit,
  sub,
  icon,
  accent = 'emerald',
  testId,
  footerBar = true,
  className = '',
  children,
}) {
  const styles = KPI_CARD_ACCENTS.get(accent) || KPI_CARD_ACCENTS.get('emerald');
  return (
    <div
      data-testid={testId}
      className={`${styles.card} ${className} rounded-lg px-2 py-1 shadow-md relative overflow-hidden flex flex-col justify-center`}
    >
      <div className="flex items-center justify-between">
        <span className={`text-[9px] font-bold uppercase tracking-wider font-mono ${styles.label}`}>
          {label}
        </span>
        <span className="text-[10px]">{icon}</span>
      </div>

      {children ?? (
        <>
          <div className="flex items-baseline gap-1.5">
            <span className={`text-sm sm:text-base font-black font-mono ${styles.value}`}>
              {value}
            </span>
            {unit && <span className={styles.unit}>{unit}</span>}
          </div>
          <span className="text-[9px] text-slate-300 truncate">{sub}</span>
        </>
      )}

      {footerBar && <div className={`absolute bottom-0 left-0 right-0 h-0.5 ${styles.bar}`} />}
    </div>
  );
}

export default KpiCard;

